import 'package:test/test.dart';

Matcher tolerant(String row) {
  final normalized = row
      .replaceAll(RegExp('\x1b\\[[0-9;?]*[a-zA-Z]'), '')
      .replaceAll(RegExp(' +'), ' ');
  final elapsed = RegExp(r'\d+s$').firstMatch(normalized);
  if (elapsed == null) return contains(normalized);
  final prefix = normalized.substring(0, elapsed.start);
  return matches(RegExp('${RegExp.escape(prefix)}\\d+s'));
}

void main() {
  test('matches any real seconds cell', () {
    expect('x ✔ bash: echo hi 1 line 1s y', tolerant('✔ bash: echo hi 1 line 0s'));
    expect('✔ bash: echo hi 1 line 0s', tolerant('✔ bash: echo hi 1 line 0s'));
    expect('✔ bash: echo hi 1 line 12s', tolerant('✔ bash: echo hi 1 line 0s'));
  });
  test('still FAILS when the row truly did not land', () {
    expect('✔ bash: echo hi', isNot(tolerant('✔ bash: echo hi 1 line 0s')),
        reason: 'no elapsed cell at all must not pass');
    expect('✔ bash: echo hi 2 lines 1s', isNot(tolerant('✔ bash: echo hi 1 line 0s')),
        reason: 'drifted meta must not pass');
    expect('◐ bash: echo hi', isNot(tolerant('✔ bash: echo hi 1 line 0s')),
        reason: 'running-phase row must not pass');
    expect('✔ bash: echo hi line 1s', isNot(tolerant('✔ bash: echo hi 1 line 0s')),
        reason: 'dropped meta must not pass');
  });
  test('elapsed-free rows stay byte-exact', () {
    expect('a echo hi b', tolerant('echo hi'));
    expect('echo', isNot(tolerant('echo hi')));
  });
}
